module device;

enum NFCErrorType {
  SECURITY,
  NOT_SUPPORTED,
  DEVICE_DISABLED,
  NOT_FOUND,
  INVALID_MESSAGE,
  OPERATION_CANCELLED,
  TIMER_EXPIRED,
  CANNOT_CANCEL,
  IO_ERROR
};

enum NFCRecordType {
  EMPTY,
  TEXT,
  URL,
  JSON,
  OPAQUE_RECORD
};

enum NFCPushTarget {
  TAG,
  PEER,
  ANY
};

enum NFCWatchMode {
  WEBNFC_ONLY,
  ANY
};

struct NFCError {
  NFCErrorType error_type;
};

struct NFCRecord {
  NFCRecordType recordType;
  string? mediaType;
  array<uint8> data;
};

struct NFCMessage {
  array<NFCRecord> data;
  string? url;
};

struct NFCPushOptions {
  NFCPushTarget target;
  double timeout;
  bool ignoreRead;
};

struct NFCRecordTypeFilter {
  NFCRecordType recordType;
};

struct NFCWatchOptions {
  string? url;
  NFCRecordTypeFilter? recordFilter;
  string? mediaType;
  NFCWatchMode mode;
};

interface NFC {
  SetClient(NFCClient client);
  Push(NFCMessage message, NFCPushOptions? options) => (NFCError? error);
  CancelPush(NFCPushTarget target) => (NFCError? error);
  Watch(NFCWatchOptions options) => (uint32 id, NFCError? error);
  CancelWatch (uint32 id) => (NFCError? error);
  CancelAllWatches () => (NFCError? error);
  SuspendNFCOperations();
  ResumeNFCOperations();
};

interface NFCClient {
  OnWatch(uint32 id, NFCMessage message);
};
